#pragma once
// Three independent princes with one transferable health pool. Ground damage
// and flying-object altitude are authoritative; clients only render er_lift.
class BloodCouncilRuntime final:public FestergutRuntime,public ICC::BloodCouncilPort {
 ICC::BloodCouncil council;std::array<entt::entity,3> princes{};std::array<std::map<uint32_t,uint64_t>,3> hate;
 uint32_t worldAt=0;bool invalid=false;uint64_t maximum=0;
 struct Nucleus {entt::entity entity;uint32_t pid=0,end=0;};std::vector<Nucleus> nuclei;
 struct Kinetic {entt::entity entity;float altitude=8;uint32_t end=0;};std::vector<Kinetic> kinetics;
 struct Flame {entt::entity entity;uint32_t pid=0,end=0;bool empowered=false;unsigned power=100;};std::vector<Flame> flames;
 struct Area {Vec point;uint32_t owner=0,at=0,end=0,next=0;float radius=8;bool empowered=false;};std::vector<Area> vortices;
 struct Bolt {entt::entity source;uint32_t pid=0,spell=0,at=0;bool released=false;};std::vector<Bolt> bolts;
 std::map<uint32_t,Vec> oldPosition;std::map<uint32_t,unsigned> prison;std::map<uint32_t,uint32_t> stillSince;std::array<uint32_t,3> swing{};
 uint32_t TankFor(unsigned index){uint32_t pid=0;double best=-1;for(auto p:Living(run)){auto id=P::GetPlayerID(p);double score=double(hate[index][id])+1/(1+Distance(Position(princes[index]),Position(p)));if(score>best){best=score;pid=id;}}return pid;}
 entt::entity RandomPlayer(){auto list=Living(run);return list.empty()?entt::null:list[random.Uniform(0,uint32_t(list.size()-1))];}
 void HitFrom(entt::entity source,entt::entity p,int64_t damage){if(Alive(run,p)&&damage>0&&Valid(source))CombatSystem::Damage(p,source,damage*(berserk?6:1),DAMAGE_TYPE_SPECIAL);}
 void Lift(entt::entity e,float height){Broadcast(run,"er_lift "+std::to_string(P::GetPacketVID(e))+" "+std::to_string(int(height*100)));}
 void Launch(unsigned prince,uint32_t spell,entt::entity p){if(!Alive(run,p)||bolts.size()>=32)return;auto source=princes[prince];M::Stop(source);M::SetRotationToXY(source,P::GetX(p),P::GetY(p));M::SendMovePacket(source,FUNC_MOB_SKILL,0,P::GetX(source),P::GetY(source),0);Fx(spell,0,p,Position(p),2000,0,source);bolts.push_back({source,P::GetPlayerID(p),spell,now+2750});}
public:
 explicit BloodCouncilRuntime(Run& r):FestergutRuntime(r,false),council(r.id^0x801){if(r.bosses.size()!=3){invalid=true;return;}std::copy_n(r.bosses.begin(),3,princes.begin());maximum=Points::GetMaxHP(princes[0]);for(auto e:princes){P::SetMaxHP(e,maximum);P::SetHP(e,maximum);}council.Reset(*this);for(auto p:Living(run))oldPosition[P::GetPlayerID(p)]=Position(p);Notice(run,"ER_COUNCIL_BEGIN");}
 ICC::Difficulty Mode()const override{return run.mode;}
 void Empower(unsigned index)override{for(unsigned i=0;i<3;i++)if(Valid(princes[i])){Fx(i==0?70952:i==1?70981:70982,4,princes[i],Position(princes[i]),0,0,princes[i]);}run.empowered=int(index);Fx(index==0?70952:index==1?70981:70982,3,princes[index],Position(princes[index]),600000,0,princes[index]);Notice(run,index==0?"ER_COUNCIL_WIND":index==1?"ER_COUNCIL_SHADOW_ACTIVE":"ER_COUNCIL_FIRE_ACTIVE");}
 void Ability(unsigned index,uint32_t spell)override{auto source=princes[index];if(!Valid(source))return;if(spell==26662){berserk=true;Fx(spell,3,source,Position(source),600000,0,source);Notice(run,"ER_ENRAGE");return;}
  if(spell==71405||spell==71815){Launch(index,spell,Resolve(TankFor(index)));return;}
  if(spell==71943){if(nuclei.size()>=12)return;auto p=RandomPlayer();if(!Alive(run,p))return;Vec at=Position(p);at.x+=4;if(!Walk(run,at))at=Position(p);auto e=Spawn(run,62030,at,1,0,38369);if(!Valid(e)){invalid=true;return;}nuclei.push_back({e,P::GetPlayerID(p),now+45000});Fx(72980,3,e,at,45000,0,e);return;}
  if(spell==72053){if(kinetics.size()>=8)return;auto p=RandomPlayer();if(!Alive(run,p))return;auto e=Spawn(run,62032,Position(p),1,0,38454);if(!Valid(e)){invalid=true;return;}kinetics.push_back({e,8,now+60000});Lift(e,8);Fx(72054,3,e,Position(p),60000,0,e);Notice(run,"ER_COUNCIL_KINETIC");return;}
  if(spell==71718||spell==72040){if(flames.size()>=8)return;auto p=RandomPlayer();if(!Alive(run,p))return;auto e=Spawn(run,62031,Position(source),1,0,spell==72040?38451:38332);if(!Valid(e)){invalid=true;return;}flames.push_back({e,P::GetPlayerID(p),now+35000,spell==72040,100});Fx(71706,3,e,Position(e),35000,0,e);Notice(run,spell==72040?"ER_COUNCIL_INFERNO":"ER_COUNCIL_FLAME");return;}
  if(spell==71806){auto p=Resolve(TankFor(index));if(!Alive(run,p))return;Hazard cone;cone.shape=Shape::Cone;cone.center=Position(source);auto target=Position(p);cone.direction={target.x-cone.center.x,target.y-cone.center.y};cone.radius=35;M::SetRotationToXY(source,P::GetX(p),P::GetY(p));M::SendMovePacket(source,FUNC_MOB_SKILL,0,P::GetX(source),P::GetY(source),0);Fx(spell,2,source,Position(source),1800,0,source);for(auto other:Living(run))if(Contains(cone,Position(other)))HitFrom(source,other,Value(spell));return;}
  if(spell==72037||spell==72039){auto targets=spell==72039?Living(run):std::vector<entt::entity>{RandomPlayer()};for(auto p:targets)if(Alive(run,p)&&vortices.size()<48){auto point=Position(p);float radius=spell==72039?12.f:8.f;vortices.push_back({point,P::GetPlayerID(p),now+4500,now+(spell==72039?5000:30000),now+4500,radius,spell==72039});Emit(point,4500,spell==72039?500:25500,int(Mechanic::Invocation),radius);Fx(spell,5,entt::null,point,4500,radius,source);}Notice(run,spell==72039?"ER_COUNCIL_SPREAD":"ER_COUNCIL_VORTEX");}
 }
 int64_t Outgoing(entt::entity,int64_t amount)override{return amount;}
 int64_t TargetDamage(entt::entity attacker,entt::entity victim,int64_t amount)override{auto pid=P::GetPlayerID(attacker);
  for(auto& n:nuclei)if(n.entity==victim){if(Participant(run,pid))n.pid=pid;return 0;}
  for(auto& k:kinetics)if(k.entity==victim){if(Participant(run,pid))k.altitude=std::min(12.f,k.altitude+4);Lift(k.entity,k.altitude);return 0;}
  for(auto& f:flames)if(f.entity==victim)return 0;
  for(unsigned i=0;i<3;i++)if(princes[i]==victim){if(Participant(run,pid)&&amount>0)hate[i][pid]+=uint64_t(amount);if(i!=council.Active())return 0;auto hp=P::GetHP(victim);auto remaining=std::max<int64_t>(0,hp-amount);for(unsigned j=0;j<3;j++)if(j!=i&&Valid(princes[j])){if(remaining)P::SetHP(princes[j],remaining);else CombatSystem::Dead(princes[j],attacker);}return amount;}return amount;
 }
 void Attacked(entt::entity,int64_t)override{}
 void Died(entt::entity)override{}
 bool Action(entt::entity p,const std::string& action,uint32_t target)override{if(action!="interact")return false;for(auto& k:kinetics)if(Valid(k.entity)&&P::GetPacketVID(k.entity)==target&&Distance(Position(p),Position(k.entity))<=20){k.altitude=std::min(12.f,k.altitude+4);Lift(k.entity,k.altitude);return true;}Notice(p,"ER_COUNCIL_NEAR_BOMB");return true;}
 void Status(entt::entity p)override{ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_council %u %u %llu %llu",run.id,council.Active(),(unsigned long long)(Valid(princes[council.Active()])?P::GetHP(princes[council.Active()]):0),(unsigned long long)maximum);for(auto& k:kinetics)if(Valid(k.entity)){ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_object %u 8",P::GetPacketVID(k.entity));ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_lift %u %u",P::GetPacketVID(k.entity),unsigned(k.altitude*100));}auto pid=P::GetPlayerID(p);unsigned stacks=0;for(auto& n:nuclei)if(n.pid==pid&&Valid(n.entity)&&Distance(Position(n.entity),Position(p))<=10)stacks++;ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effects_clear 0");if(stacks)ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effect 71822 %u 0",stacks);if(prison[pid])ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effect 72998 %u 0",prison[pid]);ecs::ChatSystem::Send(p,CHAT_TYPE_COMMAND,"er_effects_end 0");}
 bool Update(uint32_t time)override{now=time;auto elapsed=now-last;last=now;if(invalid)return false;council.Tick(*this,elapsed);
  for(size_t i=0;i<bolts.size();){if(!bolts[i].released&&Due(now,bolts[i].at-750)){bolts[i].released=true;auto p=Resolve(bolts[i].pid);if(Alive(run,p))Fx(bolts[i].spell,1,p,Position(p),750,0,bolts[i].source);}if(!Due(now,bolts[i].at)){++i;continue;}auto b=bolts[i];bolts.erase(bolts.begin()+i);auto p=Resolve(b.pid);if(!Alive(run,p))continue;unsigned stacks=0;for(auto& n:nuclei)if(n.pid==b.pid&&Valid(n.entity)&&Distance(Position(n.entity),Position(p))<=10)stacks++;auto damage=int64_t(Value(b.spell)*std::pow(.65,double(stacks)));Fx(b.spell,2,p,Position(p),1500,0,b.source);HitFrom(b.source,p,damage);}
  for(size_t i=0;i<vortices.size();){auto& a=vortices[i];if(Due(now,a.end)){vortices.erase(vortices.begin()+i);continue;}if(Due(now,a.next)){a.next=now+1000;Fx(a.empowered?72039:71945,5,entt::null,a.point,1300,a.radius,princes[0]);for(auto p:Living(run))if((!a.empowered||P::GetPlayerID(p)!=a.owner)&&Distance(Position(p),a.point)<=a.radius)HitFrom(princes[0],p,Value(a.empowered?72039:71945));}++i;}
  for(size_t i=0;i<kinetics.size();){auto& k=kinetics[i];if(!Valid(k.entity)||Due(now,k.end)){Destroy(k.entity);kinetics.erase(kinetics.begin()+i);continue;}k.altitude-=float(elapsed)*.001f;if(k.altitude<=0){auto point=Position(k.entity);Fx(72052,5,entt::null,point,2000,20,k.entity);for(auto p:Living(run))if(Distance(Position(p),point)<=20)HitFrom(princes[0],p,Value(72052));Destroy(k.entity);kinetics.erase(kinetics.begin()+i);continue;}++i;}
  if(!Due(now,worldAt))return !invalid;worldAt=now+1000;
  for(size_t i=0;i<nuclei.size();){auto& n=nuclei[i];auto p=Resolve(n.pid);if(!Valid(n.entity)||Due(now,n.end)){Destroy(n.entity);nuclei.erase(nuclei.begin()+i);continue;}if(Alive(run,p)&&Distance(Position(n.entity),Position(p))>4&&Walk(run,Position(p)))M::Goto(n.entity,P::GetX(p),P::GetY(p));++i;}
  for(auto& k:kinetics)if(Valid(k.entity))Lift(k.entity,k.altitude);
  for(size_t i=0;i<flames.size();){auto& f=flames[i];auto p=Resolve(f.pid);if(!Valid(f.entity)||!Alive(run,p)||Due(now,f.end)){Destroy(f.entity);flames.erase(flames.begin()+i);continue;}auto point=Position(f.entity);if(f.empowered)for(auto other:Living(run))if(other!=p&&Distance(Position(other),point)<=10){f.power=f.power>10?f.power-10:10;HitFrom(princes[2],other,Value(71709));}if(Distance(point,Position(p))<=3){Fx(71714,5,p,Position(p),1600,10,f.entity);for(auto other:Living(run))if(Distance(Position(other),point)<=10)HitFrom(princes[2],other,Value(71714)*f.power/100);Destroy(f.entity);flames.erase(flames.begin()+i);continue;}if(Walk(run,Position(p)))M::Goto(f.entity,P::GetX(p),P::GetY(p));++i;}
  for(unsigned i:{0u,2u}){auto p=Resolve(TankFor(i));if(!Alive(run,p))continue;auto e=princes[i];if(Distance(Position(e),Position(p))>5.5f){if(Walk(run,Position(p)))M::Goto(e,P::GetX(p),P::GetY(p));}else if(Due(now,swing[i])){swing[i]=now+2000;M::Stop(e);M::SetRotationToXY(e,P::GetX(p),P::GetY(p));M::SendMovePacket(e,FUNC_ATTACK,0,P::GetX(e),P::GetY(e),0);HitFrom(e,p,CalcMeleeDamage(e,p));}}
  if(ICC::Heroic(run.mode))for(auto p:Living(run)){auto pid=P::GetPlayerID(p);if(Distance(Position(p),oldPosition[pid])>.5f){prison[pid]=std::min(20u,prison[pid]+1);stillSince[pid]=now;HitFrom(princes[0],p,Value(72999)*prison[pid]);}else if(now-stillSince[pid]>=4000)prison[pid]=0;oldPosition[pid]=Position(p);}return !invalid;
 }
};
